triangles[i]]).z+target.transform.TransformPoint(vertices[triangles[i+1]]).z+target.transform.TransformPoint(vertices[triangles[i+2]]).z)/3;if(z<594||z>608)keep.AddRange(new[]{triangles[i],triangles[i+1],triangles[i+2]});}mesh.SetTriangles(keep,0);}mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();EditorUtility.CopySerialized(mesh,owned);UnityEngine.Object.DestroyImmediate(mesh);EditorUtility.SetDirty(owned);var shape=target.GetComponent<MeshCollider>();shape.sharedMesh=null;shape.sharedMesh=owned;}finally{foreach(var root in UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects())if(!roots.Contains(root.GetInstanceID()))UnityEngine.Object.DestroyImmediate(root);}}
