  public static void RepairStagingRoadAndCliff()
  {
   EditorSceneManager.OpenScene(AvalancheAuthoring.Scene);m=UnityEngine.Object.FindAnyObjectByType<AvalancheMatch>();var roads=GameObject.Find("Existing EasyRoads authored evacuation network");if(roads==null)throw new InvalidOperationException("Saved owned road network required.");
   foreach(var f in roads.GetComponentsInChildren<MeshFilter>()){var mesh=f.sharedMesh;if(!AssetDatabase.GetAssetPath(mesh).StartsWith("Assets/TruckAvalancheEscape/Meshes/",StringComparison.Ordinal))throw new InvalidOperationException("Only owned baked road vertices may be repaired.");var vertices=mesh.vertices;bool changed=false;for(int i=0;i<vertices.Length;i++){var p=f.transform.TransformPoint(vertices[i]);p.y=m.world.FrontHeight(p.z);vertices[i]=f.transform.InverseTransformPoint(p);changed=true;}if(changed){mesh.vertices=vertices;mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);var shape=f.GetComponent<MeshCollider>();shape.sharedMesh=null;shape.sharedMesh=mesh;}}
   if(GameObject.Find("Actual curved cliff-gap takeoff ramp")==null){var vertices=new System.Collections.Generic.List<Vector3>();var uv=new System.Collections.Generic.List<Vector2>();var triangles=new System.Collections.Generic.List<int>();for(int i=0;i<=14;i++){float t=i/14f;var p=At(1,580+14*t);var right=Vector3.Cross(Vector3.up,(At(1,p.z+1)-p).normalized).normalized;p.y+=3.6f*t*t+.025f;vertices.Add(p-right*8.5f);vertices.Add(p+right*8.5f);uv.Add(new Vector2(0,t*3));uv.Add(new Vector2(3,t*3));if(i<14){int a=i*2;triangles.AddRange(new[]{a,a+2,a+1,a+1,a+2,a+3});}}var mesh=new Mesh{name="Owned continuous cliff-gap takeoff"};mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateTangents();AssetDatabase.CreateAsset(mesh,"Assets/TruckAvalancheEscape/Meshes/Actual curved cliff takeoff.asset");var ramp=new GameObject("Actual curved cliff-gap takeoff ramp");ramp.AddComponent<MeshFilter>().sharedMesh=mesh;ramp.AddComponent<MeshRenderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckAvalancheEscape/Materials/Packed Weatherade snow roads.mat");ramp.AddComponent<MeshCollider>().sharedMesh=mesh;ramp.AddComponent<LWS.TruckTaxi.TruckTaxiSurface>().isRoad=true;ramp.AddComponent<LWS.InterstateHauler.LwsRoadSurface>().Configure("avalanche.cliff.takeoff","avalanche.cliff.takeoff",LWS.InterstateHauler.LwsRoadSurfaceType.AsphaltInterstate,"Avalanche cliff takeoff");var steel=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckAvalancheEscape/Materials/Weathered expedition galvanized steel.mat");for(int i=1;i<=4;i++)foreach(int side in new[]{-1,1}){float t=i/4f;var p=At(1,580+14*t);float height=3.6f*t*t;p+=Vector3.right*side*8.7f+Vector3.up*height*.5f;SportsEventAuthoring.Box("Grounded visible cliff-ramp steel support",p,new Vector3(.35f,Mathf.Max(.1f,height),.35f),steel);}}
   Physics.SyncTransforms();EditorSceneManager.SaveScene(m.gameObject.scene);AssetDatabase.SaveAssets();
  }
