  public static void AlignTerrainUnderExistingRoads()
  {
   // Preserve the authored EasyRoads meshes. The coarse cloned terrain must
   // remain below them, including its bilinear samples at the staging edge.
   EditorSceneManager.OpenScene(AvalancheAuthoring.Scene);m=UnityEngine.Object.FindAnyObjectByType<AvalancheMatch>();var terrain=m.world.terrain;var data=terrain.terrainData;int count=data.heightmapResolution;var heights=data.GetHeights(0,0,count,count);
   for(int z=0;z<count;z++)for(int x=0;x<count;x++){var p=new Vector3(terrain.transform.position.x+x/(float)(count-1)*data.size.x,0,terrain.transform.position.z+z/(float)(count-1)*data.size.z);float original=terrain.transform.position.y+heights[z,x]*data.size.y,result=original;foreach(var route in m.world.routes){float inner=(route.shortcut?8.5f:33)+15;for(int i=1;i<route.points.Length;i++){var a=route.points[i-1];var b=route.points[i];var delta=new Vector2(b.x-a.x,b.z-a.z);float t=Mathf.Clamp01(Vector2.Dot(new Vector2(p.x-a.x,p.z-a.z),delta)/Mathf.Max(.01f,delta.sqrMagnitude));var closest=Vector3.Lerp(a,b,t);float distance=Vector2.Distance(new Vector2(p.x,p.z),new Vector2(closest.x,closest.z));if(distance>inner+16)continue;float blend=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(inner,inner+16,distance));result=Mathf.Min(result,Mathf.Lerp(original,closest.y-.8f,blend));}}heights[z,x]=(result-terrain.transform.position.y)/data.size.y;}
   data.SetHeights(0,0,heights);terrain.Flush();EditorUtility.SetDirty(data);EditorSceneManager.SaveScene(m.gameObject.scene);AssetDatabase.SaveAssets();DebrisModels();
  }
