  static Vector3 At(int route,float z){var a=m.world.routes[route].points;for(int i=1;i<a.Length;i++)if(z<=a[i].z)return Vector3.Lerp(a[i-1],a[i],Mathf.InverseLerp(a[i-1].z,a[i].z,z));return a[a.Length-1];}
