   var terrain=m.world.terrain;var data=terrain.terrainData;int res=data.heightmapResolution;var h=data.GetHeights(0,0,res,res);for(int z=0;z<res;z++){float wz=terrain.transform.position.z+z/(float)(res-1)*data.size.z;if(wz<from||wz>to)continue;for(int x=0;x<res;x++){float wx=terrain.transform.position.x+x/(float)(res-1)*data.size.x;if(Mathf.Abs(wx-center.x)>halfX)continue;h[z,x]=Mathf.Min(h[z,x],(center.y-depth-terrain.transform.position.y)/data.size.y);}}data.SetHeights(0,0,h);
  }
  static void Bridge(Transform parent)
