   const float start=1510,end=1560;var center=At(0,(start+end)*.5f);Lower(center,650,start,end,27);var surface=GameObject.CreatePrimitive(PrimitiveType.Plane);surface.name="Frozen river visible below genuine road bridges";surface.transform.SetParent(parent,true);surface.transform.position=center+Vector3.down*24;surface.transform.localScale=new Vector3(130,1,5);UnityEngine.Object.DestroyImmediate(surface.GetComponent<Collider>());surface.GetComponent<Renderer>().sharedMaterial=water;surface.AddComponent<LWS.TruckFishing.FishingWaterFlow>();
   foreach(int route in new[]{0,2}){float width=route==0?66:17;var a=At(route,start);var b=At(route,end);var mid=(a+b)*.5f;var group=new GameObject(route==0?"Safe alpine reinforced bridge":"Narrow risky glacier ice bridge").transform;group.SetParent(parent,true);group.SetPositionAndRotation(mid,Quaternion.LookRotation(b-a));float length=Vector3.Distance(a,b);SportsEventAuthoring.Box("Visible structural bridge underside",new Vector3(0,-.8f,0),new Vector3(width,1.5f,length),route==0?steel:ice,null,group);foreach(int side in new[]{-1,1})for(int j=0;j<5;j++){float z=(j/4f-.5f)*length;SportsEventAuthoring.Box("Actual grounded bridge pier",new Vector3(side*(width*.5f+1),-13,z),new Vector3(1.5f,26,1.5f),steel,contact,group);if(route==0)SportsEventAuthoring.Box("Bridge safety rail upright",new Vector3(side*(width*.5f+1),1.5f,z),new Vector3(.3f,3,.3f),coral,contact,group);}if(route==0)foreach(int side in new[]{-1,1})SportsEventAuthoring.Box("Continuous safe-route bridge guardrail",new Vector3(side*(width*.5f+1),2,0),new Vector3(.4f,.4f,length),steel,contact,group);}
  }
  static void CliffJump(Transform parent)
