   var sign=SportsEventAuthoring.Label("Readable genuine shortcut jump warning","RAVINE GAP · KEEP YOUR SPEED",At(1,from-30)+new Vector3(-15,7,0),.1f,new Color(1,.65f,.1f));sign.transform.SetParent(parent,true);
